package com.parcelproof;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="users") class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String fullName; @Column(nullable=false,unique=true) String email; @Column(nullable=false) String password; @Enumerated(EnumType.STRING) UserRole role; String phone; @Column(length=300) String address; @Enumerated(EnumType.STRING) UserStatus status=UserStatus.ACTIVE; String vehicleNumber; @Enumerated(EnumType.STRING) VehicleType vehicleType; String licenseNumber; @Enumerated(EnumType.STRING) AvailabilityStatus availabilityStatus; @Enumerated(EnumType.STRING) CustomerType customerType; String city; String postalCode; LocalDateTime createdAt; LocalDateTime updatedAt; @PrePersist void c(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=LocalDateTime.now();}}
@Entity @Table(name="parcels") class Parcel{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String trackingCode; @Column(nullable=false) String senderName; @Column(nullable=false) String senderPhone; @Column(nullable=false,length=300) String senderAddress; @Column(nullable=false) String receiverName; @Column(nullable=false) String receiverPhone; @Column(nullable=false,length=300) String receiverAddress; @Column(nullable=false) String receiverCity; @Enumerated(EnumType.STRING) ParcelType parcelType; @Column(nullable=false) BigDecimal weight; @Column(nullable=false) BigDecimal deliveryFee; @Enumerated(EnumType.STRING) PaymentStatus paymentStatus; @Enumerated(EnumType.STRING) ParcelPriority priority; @Enumerated(EnumType.STRING) ParcelStatus status=ParcelStatus.BOOKED; @ManyToOne(fetch=FetchType.LAZY) AppUser assignedDriver; @ManyToOne(fetch=FetchType.LAZY) AppUser customer; @ManyToOne(fetch=FetchType.LAZY) AppUser createdBy; LocalDate pickupDate; @Column(nullable=false) LocalDate expectedDeliveryDate; LocalDateTime deliveredAt; @Column(nullable=false,length=6) String deliveryOtp; Boolean otpVerified=false; @Column(length=300) String proofNote; String proofPhotoPath; LocalDateTime createdAt; LocalDateTime updatedAt; @PrePersist void c(){createdAt=LocalDateTime.now();updatedAt=createdAt;if(status==null)status=ParcelStatus.BOOKED;} @PreUpdate void u(){updatedAt=LocalDateTime.now();}}
@Entity @Table(name="delivery_attempts") class DeliveryAttempt{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) Parcel parcel; @ManyToOne(fetch=FetchType.LAZY) AppUser driver; Integer attemptNumber; @Enumerated(EnumType.STRING) AttemptStatus attemptStatus; @Enumerated(EnumType.STRING) FailureReason failureReason; @Column(length=300) String notes; String proofPhotoPath; Boolean otpVerified=false; LocalDateTime attemptedAt; @PrePersist void c(){attemptedAt=LocalDateTime.now();}}
@Entity @Table(name="parcel_timeline") class ParcelTimeline{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) Parcel parcel; @Enumerated(EnumType.STRING) ParcelStatus status; @Column(nullable=false,length=300) String description; @ManyToOne(fetch=FetchType.LAZY) AppUser updatedBy; String locationNote; Boolean publicVisible=true; LocalDateTime createdAt; ParcelTimeline(){} ParcelTimeline(Parcel p,ParcelStatus s,String d,AppUser u,boolean v){parcel=p;status=s;description=d;updatedBy=u;publicVisible=v;} @PrePersist void c(){createdAt=LocalDateTime.now();}}
@Entity @Table(name="audit_logs") class AuditLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) AppUser user; String action; String entityType; Long entityId; @Column(length=400) String description; LocalDateTime createdAt; AuditLog(){} AuditLog(AppUser u,String a,String t,Long id,String d){user=u;action=a;entityType=t;entityId=id;description=d;} @PrePersist void c(){createdAt=LocalDateTime.now();}}
